`,raw:"",frontmatter:be,filepath:"",start:131,id:5,no:6},__clicksContext:null,__preloaded:!1}),vi={},we=R(vi),bi=V({get layout(){return we.layout},get transition(){return we.transition},get class(){return we.class},get clicks(){return we.clicks},get name(){return we.name},get preload(){return we.preload},slide:{content:"",revision:"2d0qlf",note:"",title:"The agent in your computer",level:1,index:6,noteHTML:`<p>[Arthur]
